<script setup lang="ts">import { getColorChannelConfig,getColorChannelValue } from '@fex-design/core/color-picker/channels';import { valueToPosition } from '@fex-design/core/color-picker/coordinates';import { colorPickerAreaThumbClassName } from '@fex-design/styles/color-picker';import { cn } from '@fex/utils';import { computed,useAttrs } from 'vue';import { useColorArea,useColorPicker } from './context';defineOptions({inheritAttrs:false});const attrs=useAttrs(),picker=useColorPicker(),area=useColorArea();const style=computed(()=>{const value=picker.snapshot.value.value;if(!value)return{display:'none'};const x=area.xChannel.value,y=area.yChannel.value,xc=getColorChannelConfig(x),yc=getColorChannelConfig(y);return{left:`${valueToPosition(getColorChannelValue(value,x),xc.min,xc.max)*100}%`,top:`${valueToPosition(getColorChannelValue(value,y),yc.min,yc.max,true)*100}%`,background:value.toString('rgb')}})</script><template><span v-bind="attrs" :class="cn(colorPickerAreaThumbClassName,attrs.class as string|undefined)" :style="[style,attrs.style]" /></template>
